"""Generated bytes: durable, budgeted, and not a capability (BLOB-01..04, CACHE-03, PERF-04).

The mesh, the thumbnail and every export were already content-addressed, which
made a cross-instance fetch *safe* — it could only 404 — without making it work.
These are the four things that had to become true for them to be resources
rather than entries in one process's memory:

1. a URL is valid on the instance that did not generate it, and after a restart;
2. a digest is a name, not a key to another tenant's part;
3. memory is bounded by bytes, because forty-eight meshes is 15 MB or 4 GB;
4. a missing blob regenerates rather than staying a broken link.
"""

from __future__ import annotations

import threading
import time

import pytest
from fastapi.testclient import TestClient

from conftest import http_part
from app.services import blobs, document_analysis, document_service as docs, singleflight
from main import app

client = TestClient(app)


@pytest.fixture
def memory_store():
    """A small store of this test's own, restored afterwards."""
    previous = blobs.store()
    yield blobs.reset_store(blobs.MemoryStore(4096, name="test"))
    blobs.reset_store(previous)


@pytest.fixture
def disk_store(tmp_path):
    previous = blobs.store()
    yield blobs.reset_store(blobs.FilesystemStore(tmp_path / "blobs", cache_bytes=2048))
    blobs.reset_store(previous)


def _blob(size: int = 100, kind: str = "text/plain") -> blobs.Blob:
    return blobs.Blob(b"x" * size, kind, "thing.txt")


# ---------------------------------------------------------------------------
# The interface
# ---------------------------------------------------------------------------

def test_a_blob_round_trips_with_its_media_type_and_filename(memory_store):
    blobs.put("doc-1", "abc", blobs.Blob(b"hello", "text/plain", "greeting.txt"))
    got = blobs.get("doc-1", "abc")
    assert got.payload == b"hello"
    assert got.media_type == "text/plain"
    assert got.filename == "greeting.txt"


def test_a_missing_blob_is_none_rather_than_an_error(memory_store):
    """The caller decides between regenerating and 404ing; the store does not."""
    assert blobs.get("doc-1", "never-written") is None


def test_a_digest_is_a_name_not_a_capability(memory_store):
    """Namespaced by document, so knowing a hash cannot reach another part.

    The route is what decides whether the caller may read the document. This is
    the structural half: there is no key that spans two namespaces.
    """
    blobs.put("doc-mine", "shared-digest", _blob())
    assert blobs.get("doc-theirs", "shared-digest") is None


def test_a_key_that_would_escape_the_blob_root_is_refused(memory_store):
    with pytest.raises(ValueError):
        blobs.put("../../etc", "passwd", _blob())
    with pytest.raises(ValueError):
        blobs.put("doc-1", "../secrets", _blob())


def test_forgetting_a_namespace_takes_everything_under_it(memory_store):
    blobs.put("doc-1", "a", _blob())
    blobs.put("doc-1", "b", _blob())
    blobs.put("doc-2", "c", _blob())
    assert blobs.forget("doc-1") == 2
    assert blobs.get("doc-1", "a") is None
    assert blobs.get("doc-2", "c") is not None


# ---------------------------------------------------------------------------
# Byte budgets
# ---------------------------------------------------------------------------

def test_memory_is_bounded_by_bytes_not_by_entries(memory_store):
    """An entry count is not a memory budget: the same forty-eight entries are
    15 MB of plates or several GB of a shelled body at resolution 256."""
    for n in range(10):
        blobs.put("doc-1", f"d{n}", _blob(1000))
    stats = blobs.stats()
    assert stats["bytes"] <= stats["max_bytes"]
    assert stats["entries"] < 10
    assert stats["evictions"] > 0


def test_a_blob_larger_than_the_whole_budget_is_kept_not_refused(memory_store):
    """Refusing it would turn a big export into a permanently broken URL."""
    blobs.put("doc-1", "huge", _blob(8192))
    assert blobs.get("doc-1", "huge") is not None


def test_reading_a_blob_makes_it_the_last_to_be_evicted(memory_store):
    blobs.put("doc-1", "old", _blob(1000))
    blobs.put("doc-1", "new", _blob(1000))
    blobs.get("doc-1", "old")            # touch it
    for n in range(4):
        blobs.put("doc-1", f"filler{n}", _blob(1000))
    # Not a strict guarantee about which survives — the budget decides how many
    # — but the touched one must not be the first to go.
    assert blobs.stats()["evictions"] >= 1


def test_the_stats_say_which_backend_is_mounted(memory_store):
    assert blobs.stats()["backend"] == "memory"


# ---------------------------------------------------------------------------
# On disk
# ---------------------------------------------------------------------------

def test_a_blob_written_to_disk_survives_the_process_that_wrote_it(disk_store, tmp_path):
    blobs.put("doc-1", "abc", blobs.Blob(b"durable", "text/plain", "f.txt"))
    # A *different* store object over the same directory is what a second API
    # instance is, and what this process is after a restart.
    other = blobs.FilesystemStore(tmp_path / "blobs", cache_bytes=2048)
    got = other.get("doc-1", "abc")
    assert got is not None and got.payload == b"durable"
    assert got.media_type == "text/plain"


def test_the_disk_store_serves_from_memory_when_it_can(disk_store):
    blobs.put("doc-1", "abc", _blob(50))
    blobs.get("doc-1", "abc")
    stats = blobs.stats()
    assert stats["backend"] == "filesystem"
    # Written once, and the read came out of the cache in front rather than off
    # the disk — the mesh endpoint is the hottest one in the system.
    assert stats["writes"] == 1
    assert stats["disk_hits"] == 0


def test_forgetting_a_namespace_removes_its_directory(disk_store, tmp_path):
    blobs.put("doc-1", "abc", _blob())
    assert (tmp_path / "blobs" / "doc-1").is_dir()
    blobs.forget("doc-1")
    assert not (tmp_path / "blobs" / "doc-1").exists()


def test_retention_expires_blobs_nothing_has_touched(disk_store):
    blobs.put("doc-1", "abc", _blob())
    assert blobs.sweep(older_than_seconds=3600) == 0
    time.sleep(0.01)
    assert blobs.sweep(older_than_seconds=0) == 1
    assert blobs.get("doc-1", "abc") is None


# ---------------------------------------------------------------------------
# Through the product
# ---------------------------------------------------------------------------

def _part() -> str:
    return http_part(client, (0.06, 0.04, 0.01), resolution=32)


def test_an_export_is_fetchable_from_a_store_the_exporting_process_did_not_hold(tmp_path):
    """The whole point of BLOB-01: a URL that works on the other instance."""
    previous = blobs.store()
    blobs.reset_store(blobs.FilesystemStore(tmp_path / "blobs", cache_bytes=1024))
    try:
        doc_id = _part()
        from app.services import artifacts

        result = artifacts.export(doc_id, "stl", resolution=32)
        # Stand up a store that has never seen the write — a cold second worker.
        blobs.reset_store(blobs.FilesystemStore(tmp_path / "blobs", cache_bytes=1024))
        fetched = client.get(result["url"])
        assert fetched.status_code == 200
        assert len(fetched.content) == result["bytes"]
    finally:
        blobs.reset_store(previous)


def test_a_mesh_that_fell_out_of_the_store_is_re_derived_not_404ed():
    doc_id = _part()
    digest = docs.get_document(doc_id).derived.mesh_hash
    blobs.forget(doc_id)
    assert document_analysis.mesh_payload(doc_id, digest) is not None


def test_deleting_a_document_takes_its_generated_bytes_with_it():
    doc_id = _part()
    digest = docs.get_document(doc_id).derived.mesh_hash
    assert docs.cached_mesh(doc_id, digest) is not None
    docs.delete_document(doc_id)
    assert docs.cached_mesh(doc_id, digest) is None


def test_gcode_is_an_artifact_rather_than_a_megabyte_of_base64():
    """It used to ride inline on the document and be stripped on persist — so a
    reload lost a program whose toolpath had not changed."""
    from app.services import cad_operations

    doc_id = _part()
    env = cad_operations.execute("slice_part", doc_id, {})
    assert env["ok"] is True, env.get("error")
    cam = docs.get_document(doc_id).derived.cam
    assert cam.gcode_url.startswith(f"/api/documents/{doc_id}/artifact/")
    # And it reads back as the program, through the route a client would use.
    assert client.get(f"/api/documents/{doc_id}/gcode").status_code == 200


def test_a_legacy_inline_gcode_url_still_reads(memory_store):
    """Documents persisted before this carry `data:text/plain;base64,…`.

    A reader that understood only the new form would 404 on a part sliced
    before a deploy, which makes people distrust the feature rather than the
    migration.
    """
    import base64

    from app.services import artifacts

    inline = "data:text/plain;base64," + base64.b64encode(b"G0 X0\n").decode()
    assert artifacts.gcode_text("doc-1", inline) == "G0 X0\n"


# ---------------------------------------------------------------------------
# In-flight deduplication
# ---------------------------------------------------------------------------

def test_two_callers_asking_the_same_question_produce_one_computation():
    group = singleflight.group("unit-test")
    started = threading.Event()
    release = threading.Event()
    runs = []

    def slow():
        runs.append(1)
        started.set()
        release.wait(2.0)
        return "answer"

    results = []
    threads = [threading.Thread(target=lambda: results.append(group.do("k", slow)))
               for _ in range(3)]
    for t in threads:
        t.start()
    started.wait(2.0)
    time.sleep(0.05)   # let the other two arrive and join
    release.set()
    for t in threads:
        t.join(timeout=3.0)

    assert results == ["answer"] * 3
    assert len(runs) == 1


def test_a_failure_is_shared_but_never_remembered():
    """A singleflight that memoised errors turns one blip into a permanent one."""
    group = singleflight.group("unit-test-fail")
    attempts = []

    def flaky():
        attempts.append(1)
        if len(attempts) == 1:
            raise RuntimeError("blip")
        return "fine"

    with pytest.raises(RuntimeError):
        group.do("k", flaky)
    assert group.do("k", flaky) == "fine"


def test_a_raising_leader_clears_its_slot():
    """Otherwise every later caller for that key waits on a future that will
    never complete — worse than the duplicate work being removed."""
    group = singleflight.group("unit-test-slot")
    with pytest.raises(ValueError):
        group.do("k", lambda: (_ for _ in ()).throw(ValueError("no")))
    assert group.stats()["in_flight"] == 0
